use xiom.io;

use xiom.string;
use xiom.convert;
fn remove_song(playlist: &mut Vec[Str], title: Str) -> Bool {
  let filtered: Vec[Str] = Vec[Str].new();
  let i = 0;
  let found = false;
  while i < playlist.len() {
    let song = match playlist.get(i) { Some(s) => s, None => "" };
    if song == title {
      found = true;
    } else {
      filtered.push(song);
    }
    i = i + 1;
  }
  while playlist.len() > 0 {
    playlist.pop();
  }
  i = 0;
  while i < filtered.len() {
    let song = match filtered.get(i) { Some(s) => s, None => "" };
    playlist.push(song);
    i = i + 1;
  }
  return found;
}

fn play_random(playlist: &Vec[Str]) -> Str {
  let len = playlist.len();
  if len == 0 {
    return "No songs";
  }
  let index = (len * 7 + 3) % len;
  return match playlist.get(index) { Some(s) => s, None => "???" };
}

fn main() -> Int {
  let playlist: Vec[Str] = Vec[Str].new();
  playlist.push("Dancing Queen");
  playlist.push("Bohemian Rhapsody");
  playlist.push("Blinding Lights");
  playlist.push("Imagine");
  playlist.push("Hotel California");

  let removed = remove_song(&mut playlist, "Imagine");
  io.println("Removed Imagine: " + convert.bool_to_string(removed));
  io.println("Songs remaining: " + to_string(playlist.len()));
  io.println("Random pick: " + play_random(&playlist));
  return 0;
}
